// ========================================
// GEMELO DIGITAL DEL SMART HOME
// ========================================

// Convertir el payload recibido
let datos = msg.payload;

if (Buffer.isBuffer(datos)) {
    datos = datos.toString("utf8");
}

if (typeof datos === "string") {
    try {
        datos = JSON.parse(datos);
    } catch (error) {
        node.warn("Gemelo digital: payload no válido");
        return null;
    }
}

// Recuperar el gemelo digital o crearlo
let gemelo = flow.get("gemeloDigital") || {
    ultimo_update: null,

    estado_actual: {
        temperatura: null,
        humedad: null,
        mq6: null,
        mq7: null,
        microfono: null,

        persona_detectada: false,
        persona_conocida: false,
        nombre_persona: null,
        confianza_persona: null,

        led: false,
        buzzer: false
    },

    historial_1h: [],

    alertas_activas: [],

    prediccion_30min: {
        temperatura: null,
        gas: null
    },

    resumen_llm: "El agente todavía no ha realizado un análisis."
};

let topic = msg.topic || "";

// ========================================
// ACTUALIZAR ESTADO SEGÚN EL TÓPICO
// ========================================

if (topic.includes("/temperatura")) {
    let valor = typeof datos === "number"
        ? datos
        : Number(datos.temperatura);

    if (Number.isFinite(valor)) {
        gemelo.estado_actual.temperatura = valor;
    }
}

else if (topic.includes("/humedad")) {
    let valor = typeof datos === "number"
        ? datos
        : Number(datos.humedad);

    if (Number.isFinite(valor)) {
        gemelo.estado_actual.humedad = valor;
    }
}

else if (topic.includes("/gas/mq6")) {
    let valor = typeof datos === "number"
        ? datos
        : Number(datos.mq6);

    if (Number.isFinite(valor)) {
        gemelo.estado_actual.mq6 = valor;
    }
}

else if (topic.includes("/gas/mq7")) {
    let valor = typeof datos === "number"
        ? datos
        : Number(datos.mq7);

    if (Number.isFinite(valor)) {
        gemelo.estado_actual.mq7 = valor;
    }
}

else if (topic.includes("/sonido/microfono")) {
    let valor = typeof datos === "number"
        ? datos
        : Number(datos.microfono);

    if (Number.isFinite(valor)) {
        gemelo.estado_actual.microfono = valor;
    }
}

else if (topic.includes("/camara/evento")) {
    gemelo.estado_actual.persona_detectada =
        datos.person_detected === true;

    gemelo.estado_actual.persona_conocida =
        datos.known_person === true;

    gemelo.estado_actual.nombre_persona =
        datos.person_name || null;

    let confianza = Number(datos.confidence);

    gemelo.estado_actual.confianza_persona =
        Number.isFinite(confianza) ? confianza : null;
}

else if (topic.includes("/control/led")) {
    gemelo.estado_actual.led =
        datos === "ON" ||
        datos.estado === true ||
        datos.estado === "ON";
}

else if (topic.includes("/control/buzzer")) {
    gemelo.estado_actual.buzzer =
        datos === "ON" ||
        datos.estado === true ||
        datos.estado === "ON";
}

// ========================================
// ÚLTIMA ACTUALIZACIÓN
// ========================================

let ahora = new Date();
gemelo.ultimo_update = ahora.toISOString();

// ========================================
// CALCULAR ALERTAS ACTIVAS
// ========================================

let alertas = [];
let estado = gemelo.estado_actual;

if (
    estado.temperatura !== null &&
    estado.temperatura > 30
) {
    alertas.push({
        tipo: "temperatura_alta",
        sensor: "temperatura",
        valor: estado.temperatura,
        umbral: 30
    });
}

if (
    estado.humedad !== null &&
    estado.humedad > 75
) {
    alertas.push({
        tipo: "humedad_alta",
        sensor: "humedad",
        valor: estado.humedad,
        umbral: 75
    });
}

if (
    estado.mq6 !== null &&
    estado.mq6 > 600
) {
    alertas.push({
        tipo: "gas_inflamable",
        sensor: "mq6",
        valor: estado.mq6,
        umbral: 600
    });
}

if (
    estado.mq7 !== null &&
    estado.mq7 > 500
) {
    alertas.push({
        tipo: "monoxido_detectado",
        sensor: "mq7",
        valor: estado.mq7,
        umbral: 500
    });
}

if (
    estado.microfono !== null &&
    estado.microfono > 900
) {
    alertas.push({
        tipo: "ruido_fuerte",
        sensor: "microfono",
        valor: estado.microfono,
        umbral: 900
    });
}

if (
    estado.persona_detectada === true &&
    estado.persona_conocida === false
) {
    alertas.push({
        tipo: "persona_desconocida",
        sensor: "camara",
        valor: estado.confianza_persona,
        umbral: 0.50
    });
}

gemelo.alertas_activas = alertas;

// ========================================
// HISTORIAL: UNA MUESTRA POR MINUTO
// ========================================

let nuevoRegistro = {
    ts: ahora.toISOString(),
    temperatura: estado.temperatura,
    humedad: estado.humedad,
    mq6: estado.mq6,
    mq7: estado.mq7,
    microfono: estado.microfono,
    persona_detectada: estado.persona_detectada
};

let historial = gemelo.historial_1h || [];
let ultimoRegistro = historial[historial.length - 1];

let minutoActual = ahora.toISOString().slice(0, 16);
let minutoAnterior = ultimoRegistro
    ? String(ultimoRegistro.ts).slice(0, 16)
    : null;

// Durante el mismo minuto se actualiza el último registro.
// Cuando cambia el minuto se agrega uno nuevo.
if (minutoAnterior === minutoActual) {
    historial[historial.length - 1] = nuevoRegistro;
} else {
    historial.push(nuevoRegistro);
}

// Mantener solamente los últimos 60 registros
if (historial.length > 60) {
    historial = historial.slice(-60);
}

gemelo.historial_1h = historial;

// ========================================
// GUARDAR EN LA MEMORIA DE NODE-RED
// ========================================

flow.set("gemeloDigital", gemelo);

// Mostrar estado debajo del nodo
if (alertas.length > 0) {
    node.status({
        fill: "red",
        shape: "dot",
        text: alertas.length + " alerta(s)"
    });
} else {
    node.status({
        fill: "green",
        shape: "dot",
        text: "Sistema normal"
    });
}

// Enviar el gemelo completo por la salida
msg.topic = "gemelo/estado";
msg.payload = gemelo;

return msg;
